<template>
  <div v-if="run" class="page" data-testid="run-detail-page">
    <div class="detail-nav"><RouterLink to="/runs"><ArrowLeft :size="14" /> 运行记录</RouterLink><span>/</span><strong>{{ run.id }}</strong></div>
    <section class="task-hero"><div><div class="task-hero__meta"><span>{{ run.id }}</span><AstraStatusBadge :status="run.status" /><span class="priority">第 {{ run.run_number }} 次运行</span></div><h2>运行详情</h2><p>{{ run.employee_id }} 在 {{ environmentLabel(run.execution_environment_snapshot) }} 工作空间处理任务 {{ run.task_id }}</p></div><div class="hero-actions"><RouterLink class="button button--primary" :to="`/tasks/${run.task_id}`">查看任务 <ArrowUpRight :size="14" /></RouterLink></div></section>
    <section class="run-summary run-summary--seven"><article><small>Token 总计</small><strong>{{ formatTokens(run.total_tokens) }}</strong><span>Agent 实际返回</span></article><article><small>输入 Token</small><strong>{{ formatTokens(run.input_tokens) }}</strong><span>模型输入</span></article><article><small>输出 Token</small><strong>{{ formatTokens(run.output_tokens) }}</strong><span>模型输出</span></article><article><small>缓存读取</small><strong>{{ formatTokens(run.cache_read_tokens) }}</strong><span>读取 Token</span></article><article><small>缓存写入</small><strong>{{ formatTokens(run.cache_write_tokens) }}</strong><span>写入 Token</span></article><article><small>工具调用</small><strong>{{ run.tool_call_count ?? '—' }}</strong><span>实际工具事件</span></article><article><small>运行时长</small><strong>{{ formatDuration(run.started_at, run.finished_at) }}</strong><span>{{ run.llm_call_count ?? '—' }} 次模型调用</span></article></section>
    <section class="detail-grid"><AstraPanel title="执行上下文" subtitle="运行开始时保存的环境快照"><dl class="info-list"><div><dt>数字员工</dt><dd>{{ run.employee_id }}</dd></div><div><dt>工作环境</dt><dd>{{ environmentLabel(run.execution_environment_snapshot) }}</dd></div><div><dt>环境模式</dt><dd>{{ executionModeLabel(run.execution_environment_snapshot.mode) }}</dd></div><div><dt>模型</dt><dd>{{ run.model_name ?? '—' }}</dd></div><div><dt>执行方式</dt><dd>{{ executorLabel(run.executor_type) }}</dd></div><div><dt>退出码</dt><dd>{{ run.exit_code ?? '—' }}</dd></div><div><dt>开始时间</dt><dd>{{ formatTime(run.started_at) }}</dd></div><div><dt>结束时间</dt><dd>{{ formatTime(run.finished_at) }}</dd></div></dl></AstraPanel><AstraPanel title="执行会话与工作空间" subtitle="用于同一任务继续处理和现场追溯"><div class="association-list"><div><TerminalSquare :size="15" /><span>执行会话</span><strong :title="run.opencode_session_id ?? ''">{{ run.opencode_session_id ?? '—' }}</strong></div><div><Server :size="15" /><span>工作空间</span><strong>{{ run.execution_environment_snapshot.workspace_root ?? '—' }}</strong></div><div><Activity :size="15" /><span>状态</span><strong>{{ statusLabel(run.status) }}</strong></div></div></AstraPanel><AstraPanel class="detail-wide" title="工具调用明细" subtitle="按 Agent 实际工具名称汇总" flush><div class="table-wrap"><table><thead><tr><th>工具名称</th><th>调用次数</th><th>成功</th><th>失败</th><th>累计耗时</th></tr></thead><tbody><tr v-for="tool in usage?.tools" :key="tool.tool_name"><td><strong>{{ tool.tool_name }}</strong></td><td>{{ tool.call_count }}</td><td>{{ tool.success_count }}</td><td>{{ tool.failure_count }}</td><td>{{ formatMilliseconds(tool.duration_ms) }}</td></tr><tr v-if="!usage?.tools.length"><td colspan="5" class="empty-cell">Agent 未返回工具调用事件</td></tr></tbody></table></div></AstraPanel></section>
  </div>
</template>
<script setup lang="ts">
import { Activity, ArrowLeft, ArrowUpRight, Server, TerminalSquare } from 'lucide-vue-next'
import { onMounted, ref } from 'vue'
import { RouterLink, useRoute } from 'vue-router'
import { api } from '@/api/client'
import type { Run, RunUsage } from '@/api/types'
import AstraPanel from '@/components/astra/AstraPanel.vue'
import AstraStatusBadge from '@/components/astra/AstraStatusBadge.vue'
import { environmentLabel, executionModeLabel, executorLabel, formatDuration, formatMilliseconds, formatTime, formatTokens, statusLabel } from '@/utils/format'
const route = useRoute(); const run = ref<Run | null>(null); const usage = ref<RunUsage | null>(null)
onMounted(async () => { [run.value, usage.value] = await Promise.all([api.run(String(route.params.id)), api.runUsage(String(route.params.id))]) })
</script>
